static void tv_unit_eventqueue_init(tv_unit_eventqueue * eq, tv_unit_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer tv_unit_eventqueue_size(tv_unit_eventqueue * eq)
{
	return eq->size;
}

static tv_unit_event tv_unit_eventqueue_pop(tv_unit_eventqueue * eq)
{
	tv_unit_event event;
	if(tv_unit_eventqueue_size(eq) <= 0) {
		tv_unit_event_init(&event, TV_Unit_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean tv_unit_eventqueue_push(tv_unit_eventqueue * eq, tv_unit_event ev)
{
	if(tv_unit_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void tv_unit_event_init(tv_unit_event * ev, TV_UnitEventID name)
{
	ev->name = name;
}

static void tV_Unit_add_event_to_queue(tv_unit_eventqueue * eq, TV_UnitEventID name)
{
	tv_unit_event event;
	tv_unit_event_init(&event, name);
	tv_unit_eventqueue_push(eq, event);
}

static sc_boolean tV_Unit_dispatch_event(TV_Unit* handle, const tv_unit_event * event) {
	switch(event->name) {
		case TV_Unit_change:
		{
			handle->iface.change_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_device_on:
		{
			handle->ifaceDevice.on_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_device_off:
		{
			handle->ifaceDevice.off_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_input_toggle:
		{
			handle->ifaceInput.toggle_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_input_satellite:
		{
			handle->ifaceInput.satellite_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_input_cable:
		{
			handle->ifaceInput.cable_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_input_hdmi:
		{
			handle->ifaceInput.hdmi_raised = bool_true;
			return bool_true;
		}
		case TV_Unit_TV_Unit__TV_Unit___TV_On__time_event_0:
		{
			handle->timeEvents.tV_Unit__TV_Unit___TV_On__tev0_raised = bool_true;
			return bool_true;
		}
		default:
			return bool_false;
	}
}

static tv_unit_event tV_Unit_get_next_event(TV_Unit* handle)
{
	tv_unit_event next_event;
	tv_unit_event_init(&next_event, TV_Unit_invalid_event);
	if(tv_unit_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = tv_unit_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean tV_Unit_dispatch_next_event(TV_Unit* handle)
{
	tv_unit_event nextEvent;
	nextEvent = tV_Unit_get_next_event(handle);
	return tV_Unit_dispatch_event(handle, &nextEvent);
}

static TV_UnitEventID tV_Unit_get_timed_event_name(TV_Unit* handle, sc_eventid evid)
{
	if(evid == &handle->timeEvents.tV_Unit__TV_Unit___TV_On__tev0_raised) {
		return TV_Unit_TV_Unit__TV_Unit___TV_On__time_event_0;
	}
	return TV_Unit_invalid_event;
}

